s=gen.S;d=s.data;model=s.model;mj=s.mj;I=gen.IKD;root=gen.PALM
s.reset();
for i in range(80):s.step(np.r_[s.targets[:7],gen.open_hand()])
p=d.xpos[gen.OBJ].copy();qo=d.xquat[gen.OBJ].copy();Ro=gen.quat_to_mat(qo)
hand=gen.close_hand();I.qpos[:]=d.qpos;I.qpos[s._jq[7:]]=hand;mj.mj_forward(model,I);Rh=I.xmat[root].reshape(3,3);tips=[]
for f in ['thumb','index']:
 b=model.body('palmleft_'+f+'_DP').id;tips.append(Rh.T@(I.xpos[b]-I.xpos[root]))
mid=np.mean(tips,axis=0);v=tips[0]-tips[1];v/=np.linalg.norm(v);z=np.array([0,0,1.]);u=np.cross(v,z);u/=np.linalg.norm(u)
Rrel=np.outer([0,1,0],u)+np.outer([0,0,1],v)+np.outer([1,0,0],z);qr=np.empty(4);mj.mju_mat2Quat(qr,Rrel.reshape(-1));qh=gen.qmul(qo,qr)
c=np.array([.10,.01,.005]);off=c-Rrel@mid;pgoal=p+Ro@off
pre=pgoal+Ro[:,0]*(-.04);print('goal',pgoal,'pre',pre)
# solve/check physical target
pstart=d.xpos[root].copy();high=np.array([pre[0],pre[1],.9])
for a,b,n,hh in [(pstart,[pstart[0],pstart[1],.9],80,gen.open_hand()),([pstart[0],pstart[1],.9],high,100,hand),(high,pre,150,hand)]:
 a=np.array(a);b=np.array(b)
 for k in range(n):gen.step_pose((1-(k+1)/n)*a+((k+1)/n)*b,qh,hh)
print('pre act',d.xpos[root].round(3),d.xpos[gen.OBJ].round(3))
for k in range(120):
 a=(k+1)/120;gen.step_pose((1-a)*pre+a*pgoal,qh,hand)
 if (k+1)%30==0:print('in',k+1,d.xpos[root].round(3),d.xpos[gen.OBJ].round(3),round(s.goal_distance(),4),d.ncon)
print('at',d.xpos[root].round(3),d.xpos[gen.OBJ].round(3),s.goal_distance())
for i in range(d.ncon):
 cc=d.contact[i];a=model.geom(cc.geom1).name;b=model.geom(cc.geom2).name
 if 'object_object_geom' in a or 'object_object_geom' in b:
  if 'table_geom' not in a and 'table_geom' not in b:print('pair',a,b,round(cc.dist,4))
for k in range(100):gen.step_pose(pgoal,qh,hand)
for k in range(240):
 gen.step_pose(pgoal+np.array([0,0,.11*(k+1)/240]),qh,hand)
 if (k+1)%60==0:print('lift',k+1,d.xpos[root].round(3),d.xpos[gen.OBJ].round(3),round(s.goal_distance(),4),d.ncon)
print('final',s.progress(),d.xpos[gen.OBJ].round(3))
